import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/auswahl-menueband.png",a="/bilder/schueler/auswahl-filter-laden-bearbeiten.png",s="/bilder/schueler/auswahl-fehlende-eintraege.png",d="/bilder/schueler/auswahl-filter-schuelergruppe.png",w=JSON.parse('{"title":"Das Menüband zur Schülerauswahl verwenden","description":"","frontmatter":{"title":"Das Menüband zur Schülerauswahl verwenden","source_pageid":309,"source_revision":4277},"headers":[],"relativePath":"schild3/schueler/menueband-auswahl.md","filePath":"schild3/schueler/menueband-auswahl.md"}'),h={name:"schild3/schueler/menueband-auswahl.md"};function u(c,e,g,m,o,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="das-menuband-zur-schulerauswahl-verwenden" tabindex="-1">Das Menüband zur Schülerauswahl verwenden <a class="header-anchor" href="#das-menuband-zur-schulerauswahl-verwenden" aria-label="Permalink to &quot;Das Menüband zur Schülerauswahl verwenden&quot;">​</a></h1><p>Nutzen Sie die Schnellzugriffe zum Zurücksetzen der Auswahl und zum Laden oder Bearbeiten gespeicherter Schülerfilter.</p><p><a href="/bilder/schueler/auswahl-menueband.png"><img src="'+l+'" alt="Das Menüband von Auswahl stellt nützliche Funktionen zur Verfügung." loading="lazy"></a></p><p><em>Das Menüband von Auswahl stellt nützliche Funktionen zur Verfügung.</em></p><p>Über das Menüband im Bereich <em>Auswahl</em> stehen mehrere Optionen für Schnellzugriffe zur Verfügung.</p><ul><li><p>Oben links findet sich der Knopf <strong>Standardauswahl</strong>. Hiermit wird die Schülerauswahl zurückgesetzt und der Container enthält wieder die Datensätze der Standardauswahl. Bereits gespeicherte Änderungen an Schülerdaten werden dadurch nicht rückgängig gemacht. Die Grundeinstellung ist <em>die ganze Schule, nach Klassen sortiert</em>.</p></li><li><p>Der Knopf <strong>Schülerfilter</strong> ruft einen sehr mächtigen Filter auf, mit dem auf nahezu alle Datenbankfelder in vielen Kombinationen gefiltert werden kann. Lesen Sie hierzu bitte den Artikel zum <em>Schülerfilter</em>.</p></li></ul><p><a href="/bilder/schueler/auswahl-filter-laden-bearbeiten.png"><img src="'+a+'" alt="Laden beziehungsweise Bearbeiten von Filterdefinitionen für den Schülerfilter." loading="lazy"></a></p><p><em>Laden beziehungsweise Bearbeiten von Filterdefinitionen für den Schülerfilter.</em></p><ul><li><p>Im <em>Schülerfilter</em> können <em>Filterdefinitionen</em> gespeichert werden, damit die Bedingungen bei öfters verwendeten Filtern nicht immer neu erstellt werden müssen.</p><ul><li>Diese können mit <em>Vorhandene Filterdefinitionen laden</em> aus einer Liste ausgewählt und mit <strong>Übernehmen</strong> direkt angewendet werden.</li><li>Mit <strong>Vorhandene Filterdefinitionen bearbeiten</strong>: Es öffnet sich ein Fenster mit den definierten Filtern, so dass Einträge zum <em>Löschen</em> ausgewählt werden können. Soll ein bestehender Filter verändert werden, ist er zuerst über diese Funktion zu löschen und dann neu anzulegen.</li></ul></li><li><p><strong>Filter auf markierte Schüler</strong>: Wie im Container können Schüler <em>markiert</em> werden und einem Klick auf dieses Feld reduziert sich die Auswahl im Container nur auf diese.</p></li></ul><p><a href="/bilder/schueler/auswahl-fehlende-eintraege.png"><img src="'+s+'" alt="Falls Felder noch nicht befüllt wurden, hilft der Filter auf fehlende Einträge diese zu finden." loading="lazy"></a></p><p><em>Falls Felder noch nicht befüllt wurden, hilft der Filter auf fehlende Einträge diese zu finden.</em></p><ul><li><p>Unter <strong>Filter auf fehlende Einträge</strong> bietet sich ein Dropdownmenü, das Daten anbietet, die üblicherweise bezüglich der Statistik eingetragen sein müssen oder sollen. Wird im Dropdownmenü eine Datenart gewählt, werden alle Schüler angezeigt, bei denen dieses Feld bislang leer ist.</p></li><li><p><strong>Schüler mit Statistik-Fehlern</strong>: Wurde über <em>Verwaltung ➜ Statistik für IT.NRW ➜ Gesamtprüfung der Daten</em> ebendiese Gesamtprüfung durchgeführt, lassen sich die gefundenen Schüler mit diesem Knopf anzeigen, so dass die gefundenen Statistikfehler abgearbeitet werden können.</p></li><li><p><strong>Schüler ohne Fächer</strong> öffnet ein Auswahlfenster, in dem ein Abschnitt zu wählen ist. Dann werden die Schüler angezeigt, für die keine Fächer eingetragen wurden.</p></li></ul><p><a href="/bilder/schueler/auswahl-filter-schuelergruppe.png"><img src="'+d+'" alt="Auswahl einer erzeugten Schülergruppe." loading="lazy"></a></p><p><em>Auswahl einer erzeugten Schülergruppe.</em></p><ul><li><p><strong>Schülergruppe auswählen</strong>: Wurden über <em>Kataloge ➜ Schülergruppe bearbeiten</em> eine Gruppe angelegt, zu der dann unter <em>Schüler</em> markierte Schüler hinzugefügt wurden (über die <em>rechte Maustaste</em>), lässt sich diese Gruppe hier auswählen.</p></li><li><p><strong>Schüler mit Geschwistern</strong> sucht nach übereinstimmendem <strong>Nachnamen</strong> und gleicher <strong>Adresse</strong>. Geschwister mit abweichendem Namen oder Wohnort können fehlen. Die Trefferliste bildet deshalb nicht jede Familiensituation vollständig ab.</p></li><li><p>Über <strong>Papierkorb zeigen</strong> werden alle Schüler mit einer Löschmarkierung gezeigt, die in der allgemeinen Schülerauswahl nicht mehr abrufbar sind. Ein Klick mit der rechten Maustaste auf einen Schüler öffnet das Kontextmenü, in dem der Eintrag <strong>Löschmarkierung aufheben</strong> den Schüler wieder zugänglich macht. Zum Löschen markierte Schüler können über die Funktion zur Prüfung der Löschfristen unter <em>Verwaltung ➜ Werkzeuge</em> dauerhaft gelöscht werden.</p></li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Men%C3%BCband_(Auswahl)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4277.</p>',17)])])}const b=n(h,[["render",u]]);export{w as __pageData,b as default};
